const brandAssets=globalThis.jejuBrandAssets||{robot:'/assets/jeju-robot.png',company:'/assets/jiwon-logo.png'};
const activities=globalThis.consultingActivities;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={user:null,requests:[],users:[],page:'home',detail:null,aiEnabled:false,filter:{},formType:'idea',parent:null,activity:null,requestDrafts:{},sketchDrafts:{},growthUserId:null,growthData:null};
const names={idea:'창업 아이디어',market:'시장조사',design:'굿즈 디자인',revision:'아이디어 수정',marketing:'홍보 · 마케팅'};
const statusNames={pending:'검토 대기',review:'후보 검토 중',released:'결과 도착'};
const icons={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',new:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>',history:'<path d="M3 12a9 9 0 1 0 3-7M3 3v6h6M12 7v6l4 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-3-5"/>',coins:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9M12 6v12"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'};
const svg=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.new}</svg>`;
const date=v=>new Date(v).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
const dayKey=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date(v));
const tag=r=>`<span class="tag ${r.status}">${statusNames[r.status]}</span>`;
const mascot=()=>`<img class="jeju-mascot" src="${brandAssets.robot}" alt="감귤과 돌하르방 모자를 쓴 지원 로봇이 웃으며 손을 흔들어요" width="480" height="640" decoding="async">`;
const company=()=>`<div class="company-signature"><img src="${brandAssets.company}" alt="지원 · JEJU STARTUP" width="92" height="78"><span>제주의 작은 아이디어를<br><strong>가능성으로 잇는 지원</strong></span></div>`;
const art=()=>`<div class="island-art mascot-scene"><span class="mascot-orbit orbit-one" aria-hidden="true"></span><span class="mascot-orbit orbit-two" aria-hidden="true"></span><span class="mascot-spark spark-one" aria-hidden="true">✦</span><span class="mascot-spark spark-two" aria-hidden="true">✧</span><div class="mascot-bubble">생각을 들려줘!<br><strong>가능성을 함께 찾아보자.</strong></div>${mascot()}<span class="mascot-caption">JEJU IDEAS, GROWING TOGETHER</span></div>`;
const brand=()=>`<div class="brand"><div class="brand-icon"><img src="${brandAssets.robot}" alt="" width="44" height="58"></div><div><strong>당신의 창업을<br>응원합니다</strong><small>WITH JIWON · JEJU STARTUP</small></div></div>`;
const isTeacher=()=>state.user?.role==='teacher';
async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const out=await r.json();if(!r.ok){if(r.status===401&&state.user){state.user=null;await boot();}throw Error(out.error||'요청에 실패했습니다.');}return out;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function load(){const m=await api('/me');state.user=m.user;state.aiEnabled=m.aiEnabled;state.requests=(await api('/requests')).requests;if(isTeacher())state.users=(await api('/users')).users;}
async function boot(){try{const b=await api('/bootstrap');if(b.needsSetup){auth(true,b.setupTokenRequired);return;}try{await load();render();}catch{auth(false);}}catch(e){$('#app').innerHTML=`<div class="loading">${esc(e.message)}<br><button class="btn" id="retry">다시 연결</button></div>`;$('#retry').onclick=boot;}}
function auth(setup,tokenRequired=false){$('#app').innerHTML=`<div class="auth"><section class="auth-art">${brand()}<div><div class="eyebrow">제주 굿즈 스타트업 도전</div><h1>제주의 작은 아이디어가<br>세상으로 향하는 시작.</h1><p>생각을 구체적으로 쓰고, 함께 다듬고, 새로운 가능성을 발견해요. 여러분의 첫 창업 도전을 응원합니다.</p>${art()}</div><div class="auth-foot auth-company">${company()}<span>생각을 표현하고, 함께 만들고, 한 걸음 성장해요.</span></div></section><section class="auth-form"><div class="auth-box"><span class="tag">${setup?'처음 오셨군요!':'제주에서 세계로'}</span><h2>${setup?'선생님 계정 만들기':'반가워요, 창업가 여러분'}</h2><p>${setup?'처음 한 번만 관리자 계정을 만들면 모둠 계정을 추가할 수 있어요.':'선생님이 안내한 모둠 아이디로 로그인해 주세요.'}</p><form id="auth-form">${setup?field('name','선생님 이름','예: 김제주 선생님',true):''}${field('username',setup?'관리자 아이디':'아이디',setup?'영문·숫자 3자 이상':'모둠 아이디',true)}${field('password','비밀번호',setup?'10자 이상으로 설정해 주세요':'비밀번호',true,'password')}${setup&&tokenRequired?field('setupToken','초기 설정 코드','배포 환경에 설정한 SETUP_TOKEN',true,'password'):''}<div class="inline-error" id="auth-error" role="alert"></div><button class="btn" type="submit">${setup?'관리자 계정 만들기':'로그인'} <span>→</span></button></form><div class="auth-foot">${setup?'계정 생성 후 로그인해 주세요. 학생 계정은 선생님만 만들 수 있습니다.':'학생은 모둠 계정을, 선생님은 관리자 계정을 사용합니다.<br>비밀번호를 잊었다면 담당 선생님께 문의해 주세요.'}</div></div></section></div>`;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const b=Object.fromEntries(new FormData(e.target));if(setup){await api('/bootstrap','POST',b);toast('선생님 계정이 만들어졌습니다. 로그인해 주세요.');auth(false);}else{await api('/login','POST',b);state.requestDrafts={};state.sketchDrafts={};state.growthData=null;state.growthUserId=null;state.parent=null;state.activity=null;await load();state.page='home';render();}}catch(err){$('#auth-error').textContent=err.message;}finally{btn.disabled=false;}};}
function field(name,label,placeholder='',required=true,type='text',value=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'autocomplete="current-password"':''} maxlength="${name==='password'?128:100}"></label>`;}
function shell(content){const teacher=isTeacher();const nav=teacher?[['home','home','대시보드'],['requests','new','의뢰서 검토'],['history','history','프로젝트 기록'],['growth','history','모둠별 성장 분석'],['users','users','모둠 · 계정 관리'],['coins','coins','코인 관리'],['settings','settings','설정']]:[['home','home','나의 창업 홈'],['new','new','컨설팅 의뢰하기'],['history','history','우리 모둠 기록'],['growth','history','나의 성장 기록'],['coins','coins','코인 사용 내역'],['settings','settings','계정 설정']];const labels=Object.fromEntries(nav.map(x=>[x[0],x[2]]));$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">${teacher?'TEACHER WORKSPACE':'OUR STARTUP JOURNEY'}</div><nav class="nav" aria-label="주 메뉴">${nav.map(([p,i,t])=>`<button data-page="${p}" class="${state.page===p?'active':''}">${svg(i)}${t}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><span class="help-spark" aria-hidden="true">✦</span><strong>작은 생각도 멋진 시작!</strong><p>우리 모둠의 아이디어를<br>차근차근 들려주세요.</p><span class="supporter-label">함께하는 회사 · 지원</span></div><div class="user-chip"><div class="avatar">${esc(state.user.name.slice(0,1))}</div><div class="grow"><strong>${esc(state.user.name)}</strong><small>${teacher?'선생님 관리자':'학생 · 모둠 계정'}</small></div><button class="text-btn" data-action="logout" aria-label="로그아웃">↪</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">우리의 창업 여정 <span> / </span> <strong>${labels[state.page]||'의뢰서 상세'}</strong></div><div class="top-right"><span class="date">${new Date().toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric'})}</span><span><i class="dot"></i>${teacher?'선생님 공간':esc(state.user.name)}</span><button class="text-btn" data-action="logout">로그아웃</button></div></header><div class="content"><div class="print-title">당신의 창업을 응원합니다 · 제주 굿즈 스타트업 도전</div>${content}<footer class="footer-note">${company()}<p>제주에서 시작해, 세상으로.<br>우리의 아이디어가 자라는 곳.</p></footer></div></main></div>`;bind();}
function heading(eyebrow,title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function stat(label,value,unit,foot){return `<div class="stat"><div class="stat-top">${label}<span>↗</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div></div>`;}
function demoNotice(){return !state.aiEnabled?'<div class="notice warning no-print">체험 모드 · AI API가 연결되지 않았습니다. 생성되는 후보와 평가는 흐름을 확인하기 위한 예시입니다.</div>':'';}
function home(){const t=isTeacher(),rs=state.requests;const greeting=t?`${esc(state.user.name)}, 안녕하세요`:`${esc(state.user.name)}의 도전을 응원해요!`;return `${heading(t?'TEACHER DASHBOARD':'YOUR IDEAS, YOUR JOURNEY',greeting,t?'모둠의 아이디어가 자라는 과정을 함께 살펴보세요.':'제주를 담은 굿즈로, 세계와 만나는 첫걸음을 시작해 볼까요?',t?'<button class="btn" data-page="requests">의뢰서 검토하기 →</button>':'<button class="btn" data-page="new">＋ 새 의뢰서 작성</button>')}<section class="hero"><div class="hero-copy"><span class="tag">JEJU GOODS STARTUP CHALLENGE</span><h2 style="margin-top:12px">작은 생각을, 멋진 가능성으로.<br>우리의 창업이 시작됩니다.</h2><p>${t?'학생의 생각을 살피고, 가능성을 함께 발견해 주세요. 모든 AI 결과는 선생님의 검토 후 전달됩니다.':'제주만의 특별함을 담아 아이디어를 키워 보세요. 창업 컨설팅팀이 여러분의 도전을 함께합니다.'}</p><button class="text-btn" data-page="${t?'history':'new'}">${t?'모둠별 성장 기록 살펴보기':'어떤 도움을 받을 수 있나요?'} ↗</button></div>${art()}</section>${demoNotice()}<div class="stats">${t?stat('함께하는 모둠',state.users.length,'모둠','함께 만드는 제주 굿즈')+stat('전체 의뢰서',rs.length,'건','누적된 창업 아이디어')+stat('검토가 필요한 의뢰',rs.filter(r=>r.status!=='released').length,'건','선생님의 피드백을 기다려요')+stat('전달한 컨설팅',rs.filter(r=>r.status==='released').length,'건','다음 도전을 응원해요'):stat('사용 가능한 코인',state.user.balance,'개',state.user.periodLimit===null?'매일 초기화 · 한국 시간 기준':'프로젝트 기간 전체 한도')+stat('보낸 의뢰서',rs.length,'건','우리 모둠의 도전 기록')+stat('기다리는 컨설팅',rs.filter(r=>r.status!=='released').length,'건','선생님이 꼼꼼히 살펴보고 있어요')+stat('도착한 결과',rs.filter(r=>r.status==='released').length,'건','새로운 아이디어를 만나 보세요')}</div>${!t?`<div class="section-head"><div><h2>어떤 도움이 필요한가요?</h2><p>우리 모둠에게 꼭 필요한 컨설팅을 골라 주세요.</p></div><span class="tag">의뢰 1회 = 코인 1개</span></div>${services()}`:''}<div class="section-head"><div><h2>${t?'최근 접수된 의뢰서':'우리 모둠의 최근 의뢰'}</h2><p>아이디어가 조금씩 구체적으로 자라고 있어요.</p></div><button class="text-btn tiny" data-page="${t?'requests':'history'}">전체 보기 →</button></div><div class="panel">${table(rs.slice(0,5))}</div>`;}
function services(){const desc={idea:'떠오른 생각을 구체적인 창업 아이디어로 함께 다듬어요.',market:'우리 굿즈와 잘 어울릴 나라와 소비자를 알아봐요.',design:'제주의 매력이 담긴 디자인 시안과 이미지를 받아요.',revision:'아쉬운 점을 보완하고 아이디어를 한 단계 발전시켜요.',marketing:'상품의 매력을 전할 소개 문구와 홍보 방법을 찾아요.'};return `<div class="service-grid">${Object.keys(names).map((k,i)=>`<button class="service" data-type="${k}"><span class="service-icon">${['♧','◎','✎','↻','⚑'][i]}</span><span class="arrow">↗</span><h3>${names[k]}</h3><p>${desc[k]}</p><small>컨설팅 의뢰하기 →</small></button>`).join('')}</div>`;}
function table(rs){if(!rs.length)return '<div class="empty"><div class="empty-icon">▤</div><h3>아직 의뢰서가 없어요</h3><p>첫 번째 아이디어를 보내면 창업 여정이 이곳에 쌓여요.</p></div>';return `<div class="table-wrap"><table><thead><tr><th>의뢰 내용</th>${isTeacher()?'<th>모둠</th>':''}<th>분야</th><th>진행 상태</th><th>제출일</th><th class="no-print"></th></tr></thead><tbody>${rs.map(r=>`<tr><td><button class="record-button" data-detail="${r.id}"><strong>${esc(r.title)}</strong></button>${r.parentId?`<div class="tiny muted">#${r.parentId}에 대한 추가 요청</div>`:''}</td>${isTeacher()?`<td>${esc(r.groupName)}</td>`:''}<td><span class="tag">${names[r.type]}</span></td><td>${tag(r)}</td><td class="muted tiny">${date(r.createdAt)}</td><td class="no-print"><button class="text-btn" data-detail="${r.id}" aria-label="${esc(r.title)} 보기">→</button></td></tr>`).join('')}</tbody></table></div>`;}
function history(){const f=state.filter;let rs=state.requests.filter(r=>(!f.status||r.status===f.status)&&(!f.group||r.userId===Number(f.group))&&(!f.date||dayKey(r.createdAt)===f.date)&&(!f.q||r.title.includes(f.q)||Object.values(r.answers).join(' ').includes(f.q)));const title=state.page==='requests'?'의뢰서 검토':'우리의 프로젝트 기록';return `${heading('OUR GROWING STORY',title,'날짜별, 모둠별로 아이디어가 자라는 과정을 확인해요.','<button class="btn secondary no-print" data-action="print">▤ 기록 출력</button>')}<div class="filters no-print"><input id="search" placeholder="의뢰 제목 또는 굿즈 검색" aria-label="의뢰 검색" value="${esc(f.q||'')}"><select id="filter-status" aria-label="상태 필터"><option value="">모든 진행 상태</option>${Object.keys(statusNames).map(k=>`<option value="${k}" ${f.status===k?'selected':''}>${statusNames[k]}</option>`).join('')}</select>${isTeacher()?`<select id="filter-group" aria-label="모둠 필터"><option value="">모든 모둠</option>${state.users.map(u=>`<option value="${u.id}" ${Number(f.group)===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`:''}<input id="filter-date" type="date" aria-label="제출 날짜 필터" value="${esc(f.date||'')}"><button class="btn secondary small" data-action="reset-filter">초기화</button></div><div class="panel"><div class="section-head" style="margin-top:0"><h3>의뢰서 <span class="muted">${rs.length}</span></h3><span class="tiny muted">제출일 · 한국 시간 기준</span></div>${table(rs)}</div>${state.page==='history'?`<div class="section-head"><h2>상세 성장 기록</h2><span class="tiny muted">의뢰 내용 · 전달 결과 · 피드백을 함께 출력할 수 있어요</span></div>${rs.map(r=>`<section class="panel" style="margin-bottom:18px"><div class="row wrap"><h3 class="grow">#${r.id} ${esc(r.title)} · ${esc(r.groupName)}</h3>${tag(r)}</div><p class="tiny">${date(r.createdAt)} · ${names[r.type]}</p>${answers(r)}${r.source==='demo'?'<div class="notice warning">체험용 예시 결과입니다. 실제 AI 분석이 아닙니다.</div>':''}${r.status==='released'?`${r.candidates.filter(c=>!isTeacher()||r.selected.includes(c.id)).map(c=>`<div class="candidate"><h3>${esc(c.title)}</h3>${resultContent(c.content)}${c.imageUrl?`<img class="design-preview" src="${c.imageUrl}" alt="후보 ${c.id} 디자인 시안">`:""}</div>`).join('')}${assessment(r.assessment)}<p>선생님 피드백: ${esc(r.teacherNote)}</p>`:'<p class="tiny">결과 전달을 기다리고 있어요.</p>'}</section>`).join('')}`:''}`;}
function sketchDraftKey(code,parentId=0){return code+':'+(parentId||0);}
function studentSketchFigure(r){const sketch=r?.sketch;if(!sketch?.imageUrl)return '';return `<figure class="student-sketch-original"><figcaption><strong>학생이 그린 원본 디자인</strong>${sketch.requestId!==r.id?` <span class="tiny">· 원본 의뢰 #${sketch.requestId}</span>`:''}</figcaption><img class="design-preview" src="${esc(sketch.imageUrl)}" alt="학생이 의뢰에 첨부한 원본 디자인 그림" loading="lazy"><p class="tiny">원본 그림을 바탕으로 생각과 시안이 어떻게 달라졌는지 함께 살펴봐요.</p></figure>`;}
function studentSketchForm(code,parent,draft){return `<section class="form-section student-sketch-section"><h3>내가 그린 디자인을 보여 주세요 (선택)</h3><label class="field"><span>그림 첨부 · PNG/JPEG/WebP · 최대 5MB</span><input id="student-sketch-file" name="sketch" type="file" accept="image/png,image/jpeg,image/webp" aria-describedby="sketch-help"><small id="sketch-help">종이에 그린 그림을 찍은 사진도 좋아요. 그림에 이름·얼굴·연락처가 들어가지 않게 확인해 주세요.</small></label><p class="tiny">선생님이 그림을 확인한 뒤, AI 연결 시 그림과 답변을 함께 참고해 디자인 조언과 시안을 준비해요.${code==='D1'&&parent?.sketch?' 새 그림을 첨부하지 않으면 이전 의뢰의 원본 그림을 계속 참고해요.':''}</p><img id="student-sketch-preview" class="design-preview" ${draft.image?`src="${esc(draft.image)}"`:''} alt="첨부할 학생 디자인 미리보기" ${draft.image?'':'hidden'}><p id="student-sketch-status" class="tiny" aria-live="polite">${draft.loading?'그림 미리보기를 준비하고 있어요…':draft.image?'선택한 그림을 의뢰서와 함께 보낼 준비가 됐어요.':''}</p><div id="student-sketch-error" class="inline-error" role="alert">${esc(draft.error||'')}</div><button type="button" class="text-btn" data-sketch-remove>첨부 취소</button></section>`;}
function bindStudentSketch(){
 const form=$('#request-form'),input=$('#student-sketch-file');if(!form||!input)return;
 const key=form.dataset.sketchKey;
 const stateFor=()=>state.sketchDrafts[key]||(state.sketchDrafts[key]={image:null,loading:false,error:'',token:0});
 const update=()=>{if(!form.isConnected)return;const draft=stateFor(),preview=$('#student-sketch-preview');preview.hidden=!draft.image;if(draft.image)preview.src=draft.image;else preview.removeAttribute('src');$('#student-sketch-error').textContent=draft.error;$('#student-sketch-status').textContent=draft.loading?'그림 미리보기를 준비하고 있어요…':draft.image?'선택한 그림을 의뢰서와 함께 보낼 준비가 됐어요.':'';};
 input.onchange=async()=>{
  const draft=stateFor(),token=++draft.token,file=input.files[0];draft.image=null;draft.error='';draft.loading=!!file;update();if(!file)return;
  try{
   if(!globalThis.studentSketchInput.types.includes(file.type))throw Error('PNG, JPEG, WebP 그림을 선택해 주세요.');
   if(file.size>globalThis.studentSketchInput.maxBytes)throw Error('학생 그림은 5MB 이하로 첨부해 주세요.');
   const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('그림 파일을 읽을 수 없습니다.'));reader.readAsDataURL(file);});
   globalThis.studentSketchInput.decode(image);const preview=new Image();preview.src=image;await preview.decode();
   if(draft.token===token){draft.image=image;draft.loading=false;update();}
  }catch(error){if(draft.token===token){draft.image=null;draft.loading=false;draft.error=error.message||'그림을 읽을 수 없습니다.';input.value='';update();}}
 };
 form.querySelector('[data-sketch-remove]').onclick=()=>{const draft=stateFor();draft.token++;draft.image=null;draft.loading=false;draft.error='';input.value='';update();};
}
function currentActivity(){const entries=Object.entries(activities).filter(([,a])=>a.type===state.formType);return entries.some(([code])=>code===state.activity)?state.activity:entries[0][0];}
function saveRequestDraft(){const form=$('#request-form');if(!form)return;state.requestDrafts[form.dataset.activity]=Object.fromEntries(new FormData(form));}
function newRequest(){
 const code=currentActivity(),activity=activities[code],draft=state.requestDrafts[code]||{},previous=state.requests.filter(r=>r.status==='released'),parent=previous.find(r=>r.id===state.parent),design=code==='C1'||(code==='D1'&&(parent?.outputType||parent?.type)==='design'),sketchKey=sketchDraftKey(code,state.parent),sketchDraft=state.sketchDrafts[sketchKey]||{};
 return `${heading('YOUR IDEAS, YOUR JOURNEY','컨설팅 의뢰하기','어떤 도움이 필요한지 고르고, 우리 모둠의 생각을 들려주세요.')}<div class="form-layout"><div><div class="notice">제출하면 코인 1개가 사용돼요. 현재 <strong>${state.user.balance}개</strong>를 사용할 수 있어요.</div><form id="request-form" class="panel" data-activity="${code}" data-sketch-key="${design?sketchKey:''}"><section class="form-section"><h3>01 &nbsp; 어떤 도움을 받고 싶나요?</h3><label class="field"><span>컨설팅 분야</span><select name="type" id="type-select">${Object.keys(names).map(k=>`<option value="${k}" ${k===state.formType?'selected':''}>${names[k]}</option>`).join('')}</select></label><label class="field"><span>세부 활동</span><select name="activity" id="activity-select">${Object.entries(activities).filter(([,a])=>a.type===state.formType).map(([key,a])=>`<option value="${key}" ${key===code?'selected':''}>${key}. ${a.name}</option>`).join('')}</select></label></section>${code==='D1'?`<section class="form-section"><h3>02 &nbsp; 먼저 수정할 결과를 골라 주세요</h3><label class="field"><span>이전 컨설팅 결과</span><select name="parentId" id="parent-select" required><option value="">결과를 선택해 주세요</option>${previous.map(r=>`<option value="${r.id}" ${r.id===state.parent?'selected':''}>#${r.id} ${esc(r.title)} · ${date(r.releasedAt)}</option>`).join('')}</select><small class="answer-example">예: 우리 모둠이 전달받은 굿즈 디자인 시안</small></label>${!previous.length?'<div class="notice warning">아직 전달받은 결과가 없어요. 선생님이 결과를 보내 주신 뒤 수정 의뢰를 할 수 있어요.</div>':''}${parent?`<details><summary>선택한 이전 결과 보기</summary>${studentSketchFigure(parent)}${parent.candidates.map(c=>`<h4>${esc(c.title)}</h4>${resultContent(c.content)}${c.imageUrl?`<img class="design-preview" src="${esc(c.imageUrl)}" alt="이전 디자인">`:''}`).join('')}</details>`:''}</section>`:''}<section class="form-section"><h3>${code==='D1'?'03':'02'} &nbsp; 우리 모둠의 생각을 적어 주세요</h3>${activity.questions.map(([question,example],i)=>`<label class="field"><span>${i+1}. ${question}</span><textarea name="q${i+1}" required maxlength="2000" aria-describedby="example-${i+1}">${esc(draft['q'+(i+1)]||'')}</textarea><small id="example-${i+1}" class="answer-example">예: ${esc(example)}</small></label>`).join('')}</section>${design?studentSketchForm(code,parent,sketchDraft):''}<section class="form-section"><label class="check"><input type="checkbox" name="safety" required ${draft.safety?'checked':''}><span>그림과 답변에 개인정보를 넣지 않았고, 다른 사람의 저작권을 존중하는 내용인지 확인했어요.</span></label><p class="tiny">이름·전화번호·주소 등 개인정보를 적지 않아요. 예시는 참고만 하고 우리 모둠의 생각을 써 주세요.</p></section><div id="form-error" class="inline-error" role="alert"></div><button class="btn" type="submit" ${state.user.balance<1||(code==='D1'&&!previous.length)?'disabled':''}>컨설팅 의뢰하기 <span>· 코인 1개</span></button></form></div><aside class="tips"><div class="tips-mascot"><img src="${brandAssets.robot}" alt="" width="58" height="77"><span>우리 모둠의 생각이<br><strong>멋진 시작이 돼요.</strong></span></div><h3>이런 도움을 받아요</h3><ul>${activity.outputs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>학생은 프롬프트를 만들 필요가 없어요. 질문에 생각을 적으면 선생님이 결과를 검토해서 보내 주세요.</p>${code==='C1'||(code==='D1'&&parent?.outputType==='design')?'<p>실제 이미지는 AI 연결이 필요해요. 체험 모드에서는 설명 예시를 확인할 수 있어요.</p>':''}</aside></div>`;
}
function answers(r){return answerText(r)+studentSketchFigure(r);}
function answerText(r){const activity=activities[r.answers.activity];if(activity)return `<p class="tiny">${esc(activity.name)}${r.parentId?' · 이전 결과 #'+r.parentId:''}</p><dl class="answer-grid">${activity.questions.map(([question],i)=>`<div class="wide"><dt>${esc(question)}</dt><dd>${esc(r.answers['q'+(i+1)])}</dd></div>`).join('')}</dl>`;const labels={goods:'제주 굿즈',country:'수출 대상국',audience:'대상 소비자',purpose:'의뢰 목적',details:'구체적인 요청',format:'원하는 결과 형식'};return `<dl class="answer-grid">${Object.keys(labels).map(k=>`<div class="${k==='details'||k==='format'?'wide':''}"><dt>${labels[k]}</dt><dd>${esc(r.answers[k])}</dd></div>`).join('')}</dl>`;}
function resultContent(content){
 const lines=String(content||'').split(/\r?\n/),parts=[];let plain=[];
 const cells=line=>line.trim().replace(/^\||\|$/g,'').split('|').map(value=>value.trim());
 const flush=()=>{if(plain.length){parts.push(`<pre>${esc(plain.join('\n'))}</pre>`);plain=[];}};
 for(let i=0;i<lines.length;i++){
  if(lines[i].trim().startsWith('|')&&lines[i+1]?.includes('|')&&cells(lines[i+1]).every(cell=>/^:?-{3,}:?$/.test(cell))){
   flush();const headings=cells(lines[i]);i+=2;const rows=[];
   while(i<lines.length&&lines[i].trim().startsWith('|')){const row=cells(lines[i]);rows.push(`<tr>${headings.map((_,j)=>`<td>${esc(row[j]||'')}</td>`).join('')}</tr>`);i++;}
   i--;parts.push(`<div class="table-wrap"><table><thead><tr>${headings.map(value=>`<th>${esc(value)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`);
  }else plain.push(lines[i]);
 }
 flush();return `<div class="result-content">${parts.join('')}</div>`;
}
function assessment(a){if(!a)return '';return `<section class="assessment"><span class="score">${a.score} / 20</span><h3>✦ 의뢰서 성장 피드백</h3><p class="tiny">목표 · 배경 · 구체성 · 결과 형식 · 안전성</p><div class="two-col"><div><h4>잘한 점</h4><ul>${a.strengths.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h4>다음에는 이렇게 해 봐요</h4><ul>${a.improvements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><p class="tiny">${esc(a.safety)}</p></section>`;}
function manualDesign(r){return `<details class="panel no-print" style="margin-top:20px"><summary><strong>교사 직접 작성 · 이미지 첨부</strong></summary><p class="tiny" style="margin:14px 0">AI 후보 대신 선생님이 준비한 디자인을 전달합니다. AI 후보 작성 없이도 사용할 수 있으며, 아래 결과만 학생에게 전달됩니다.</p><form id="manual-design-form">${field('title','디자인 제목','',true)}<label class="field"><span>요약</span><input name="summary" maxlength="500" required></label><label class="field"><span>디자인 설명</span><textarea name="content" maxlength="7000" required></textarea></label><label class="field"><span>이미지 첨부 (선택 · PNG, JPEG, WebP · 최대 5MB)</span><input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label><img id="manual-preview" class="design-preview" alt="첨부할 디자인 미리보기" hidden><label class="field"><span>선생님 한마디 (선택)</span><textarea name="teacherNote" maxlength="3000"></textarea></label><label class="check"><input name="reviewConfirmed" type="checkbox" required><span>내용과 이미지를 확인했으며 개인정보·저작권·문화 표현과 사실 여부를 검토했습니다.</span></label><div id="manual-error" class="inline-error" role="alert"></div><button class="btn" type="submit">직접 작성한 디자인 전송 →</button></form></details>`;}
function detail(){const r=state.requests.find(r=>r.id===state.detail);if(!r)return '<div class="empty">의뢰서를 찾을 수 없습니다.</div>';const teacher=isTeacher(),editable=teacher&&r.status==='review';return `<button class="text-btn back no-print" data-page="${teacher?'requests':'history'}">← 의뢰 목록으로</button><div class="detail-head"><div class="row wrap"><span class="tag">${names[r.type]}</span>${tag(r)}<span class="tiny muted">#${r.id}${r.parentId?` · 원본 #${r.parentId}`:''}</span></div><h1>${esc(r.title)}</h1><p>${esc(r.groupName)} · ${date(r.createdAt)}</p></div><section class="panel"><h3>학생이 작성한 의뢰서</h3>${answers(r)}</section>${r.source==='demo'?'<div class="notice warning" style="margin-top:20px">체험용 예시 결과입니다. 실제 AI가 분석한 시장조사나 평가가 아닙니다.</div>':''}${teacher&&r.status!=='released'?`<div class="panel no-print" style="margin-top:20px"><h3>컨설팅 후보 준비</h3><p class="tiny" style="margin:8px 0 15px">${state.aiEnabled?((r.outputType||r.type)==='design'&&r.answers.activity?'설정된 AI로 설명과 실제 디자인 이미지 3개를 요청합니다. 이미지 API 비용이 발생합니다.':'설정된 AI로 활동에 맞는 후보 3개와 의뢰서 평가를 요청합니다.'):'AI 미연결 상태입니다. 흐름 확인용 예시 후보 3개를 작성합니다. 실제 이미지는 생성하지 않습니다.'} 학생에게는 아직 공개되지 않습니다.</p><button class="btn" data-generate="${r.id}">${r.status==='review'?'후보 다시 작성':'후보 3개 작성'} ${state.aiEnabled?'✦':'(체험)'}</button><span class="tiny muted"> 학생 코인 추가 차감 없음</span><div id="generate-error" class="inline-error" role="alert"></div></div>`:''}${teacher&&(r.outputType||r.type)==='design'&&r.status!=='released'?manualDesign(r):''}${r.candidates?.length?`<div class="section-head"><h2>${teacher?'컨설팅 후보 검토':'우리 모둠에 도착한 컨설팅'}</h2><button class="btn secondary small no-print" data-action="print">결과 출력</button></div>${teacher&&r.status==='review'?'<div class="notice">후보를 1개 이상 선택해 주세요. 제목·요약·제안 내용을 고친 뒤 전송할 수 있습니다.</div>':''}<form id="release-form">${r.candidates.map(c=>`<section class="candidate ${r.selected?.includes(c.id)?'selected':''}">${editable?`<label class="check"><input type="checkbox" name="selected" value="${c.id}"><strong>후보 ${c.id} · 학생에게 전달하기</strong></label><label class="field"><span>후보 제목</span><input name="title-${c.id}" value="${esc(c.title)}" maxlength="100" required></label><label class="field"><span>요약</span><input name="summary-${c.id}" value="${esc(c.summary)}" maxlength="500" required></label><label class="field"><span>제안 내용</span><textarea name="content-${c.id}" maxlength="7000" required>${esc(c.content)}</textarea></label>`:`<span class="tag">${c.id===4?'교사 직접 작성':'제안 '+c.id}${teacher&&r.selected?.includes(c.id)?' · 전달 완료':''}</span><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p>${resultContent(c.content)}`}${c.imageUrl?`<img class="design-preview" src="${c.imageUrl}" alt="후보 ${c.id} 디자인 시안" loading="lazy">`:''}${editable&&(r.outputType||r.type)==='design'?`<div class="no-print"><p class="tiny">실제 이미지 생성은 AI API 연결이 필요하며 별도 API 비용이 발생합니다. 학생 코인은 차감되지 않습니다. 이미지도 검토 후 전송해 주세요.</p><button class="btn secondary small" type="button" data-image="${r.id}" data-candidate="${c.id}" ${!state.aiEnabled?'disabled':''}>${c.imageUrl?'시안 이미지 다시 생성':'시안 이미지 생성'}</button></div>`:''}</section>`).join('')}${assessment(r.assessment)}${editable?`<section class="panel no-print"><h3>선생님의 검토와 피드백</h3><p class="tiny" style="margin:8px 0 14px">의뢰서 평가는 참고 자료입니다. 아래에서 평가 내용도 수정할 수 있어요.</p>${field('score','의뢰서 평가 점수 (0~20)','',true,'number',r.assessment.score)}<label class="field"><span>잘한 점 (한 줄에 하나)</span><textarea name="strengths" required>${esc(r.assessment.strengths.join('\n'))}</textarea></label><label class="field"><span>보완할 점 (한 줄에 하나)</span><textarea name="improvements" required>${esc(r.assessment.improvements.join('\n'))}</textarea></label><label class="field"><span>안전·사실 확인 사항</span><textarea name="safety" required>${esc(r.assessment.safety)}</textarea></label><label class="field"><span>모둠에게 전할 선생님 한마디</span><textarea name="teacherNote" maxlength="3000" required placeholder="아이디어를 응원하고 다음 활동을 안내해 주세요.">${esc(r.teacherNote)}</textarea></label><label class="check"><input name="reviewConfirmed" type="checkbox" required><span>선택한 결과와 평가에 개인정보, 저작권 침해, 문화 왜곡·편향, 확인되지 않은 사실이 없는지 검토했습니다.</span></label><div id="release-error" class="inline-error" role="alert"></div><button type="submit" class="btn">선택한 결과와 평가 전송 →</button></section>`:`<section class="panel"><h3>선생님의 한마디</h3><p style="margin-top:10px;white-space:pre-wrap">${esc(r.teacherNote)}</p>${r.releasedAt?`<p class="tiny" style="margin-top:10px">전달일 ${date(r.releasedAt)}</p>`:''}</section>`}</form>`:!teacher?'<div class="empty"><div class="empty-icon">✉</div><h3>선생님이 의뢰서를 살펴보고 있어요</h3><p>결과가 전달되면 이곳에서 확인할 수 있어요.</p></div>':''}${!teacher&&r.status==='released'?`<div class="panel no-print" style="margin-top:20px"><h3>조금 더 다듬고 싶은 부분이 있나요?</h3><p class="tiny" style="margin:8px 0 15px">기존 의뢰와 연결해 추가 요청을 보낼 수 있어요. 코인 1개가 사용됩니다.</p><button class="btn" data-followup="${r.id}">이 결과 수정 의뢰하기 →</button></div>`:''}`;}
function users(){return `${heading('TOGETHER, WE GROW','모둠 · 계정 관리','학생 개인정보 대신 모둠 이름과 아이디를 사용해 주세요.','<button class="btn" data-action="add-user">＋ 모둠 계정 추가</button>')}<div class="notice">모둠별 계정으로 로그인합니다. 비밀번호는 10자 이상이며 선생님이 재설정할 수 있어요.</div><div class="panel">${state.users.length?`<div class="table-wrap"><table><thead><tr><th>모둠</th><th>아이디</th><th>코인 운영</th><th>잔여 코인</th><th>상태</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.username)}</td><td>${u.periodLimit===null?`하루 ${u.dailyLimit}개`:`기간 전체 ${u.periodLimit}개`}</td><td>${u.balance}개</td><td><span class="tag">${u.active?'사용 중':'사용 중지'}</span></td><td><button class="btn secondary small" data-edit-user="${u.id}">관리</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>첫 모둠을 추가해 주세요</h3><p>모둠 계정을 만든 뒤 학생들에게 아이디와 비밀번호를 안내하세요.</p></div>'}</div>`;}
function settings(){return `${heading('WORKSPACE SETTINGS','계정과 연결 설정','안전하게 계정을 관리하고 AI 연결 상태를 확인해요.')}<div class="two-col"><section class="panel"><h3>비밀번호 변경</h3><form id="password-form" style="margin-top:20px">${field('currentPassword','현재 비밀번호','',true,'password')}${field('password','새 비밀번호','10자 이상',true,'password')}<button class="btn">비밀번호 변경</button><div id="password-error" class="inline-error" role="alert"></div></form></section><section class="panel"><h3>${isTeacher()?'AI 연결 상태':'우리 프로젝트 안내'}</h3>${isTeacher()?`<div class="notice ${state.aiEnabled?'':'warning'}" style="margin-top:20px">${state.aiEnabled?'AI 연결 설정이 있습니다. 실제 후보 생성 성공 여부는 의뢰서 검토 화면에서 확인해 주세요.':'체험 모드 · AI API 키가 설정되지 않았습니다.'}</div><p class="tiny">실제 연결은 배포 서버의 환경 변수 <strong>AI_API_KEY</strong>로 설정합니다. 키를 학생 화면이나 의뢰서에 입력하지 마세요. 기본 모델은 gpt-4.1-mini이며 AI_MODEL로 변경할 수 있습니다.</p><p class="tiny" style="margin-top:14px">AI에 전송되는 내용: 선택한 활동과 질문별 답변, 수정 의뢰의 이전 결과. 그림을 첨부한 디자인 의뢰는 교사가 후보 작성을 실행할 때 원본 그림도 AI에 전송합니다. 성장 분석은 의뢰 이력과 컨설팅 초안·최종 결과 설명을 사용하며, 그림의 시각적 변화 자체를 평가하지 않습니다. 학생 개인정보는 의뢰서에 입력하지 않도록 지도해 주세요.</p><p class="tiny" style="margin-top:14px">새 디자인 의뢰와 디자인 수정 의뢰는 설명과 실제 이미지를 함께 준비합니다. 실패한 이미지는 각 후보에서 다시 생성하거나 직접 첨부할 수 있습니다. 이미지 API 사용 권한과 별도 비용이 필요합니다.</p>`:'<p style="margin-top:20px">우리는 제주 굿즈를 만들며 좋은 질문을 쓰는 방법을 배워요. AI가 제안한 내용은 선생님이 검토한 후 전달됩니다.</p><p class="tiny" style="margin-top:15px">개인정보를 지키고 다른 사람의 창작물을 존중해요. 국가와 문화에 대한 정보는 여러 자료로 확인해요.</p>'}</section></div>`;}
async function coins(){shell(`${heading('EVERY QUESTION COUNTS','코인 사용과 관리',isTeacher()?'코인을 조정하고 모둠별 사용 내역을 확인해요.':'신중하게 질문하고 소중하게 사용해요. 의뢰 한 번에 코인 1개가 사용됩니다.')}<div class="loading-note">사용 내역을 불러오고 있어요…</div>`);try{const {entries}=await api('/ledger');if(state.page!=='coins')return;shell(`${heading('EVERY QUESTION COUNTS','코인 사용과 관리',isTeacher()?'기본 하루 3개 · 매일 00시(한국 시간)에 사용 가능한 개수가 초기화됩니다.':'오늘의 좋은 질문이 내일의 멋진 아이디어가 돼요.')}<div class="notice">하루 모드: 미사용 코인은 이월되지 않습니다. 추가·삭감은 당일 잔액에 적용됩니다.<br>기간 전체 모드: 매일 초기화하지 않습니다. 운영 방식을 바꾸면 새 한도로 잔액이 설정됩니다.</div>${isTeacher()?`<div class="panel" style="margin-bottom:20px"><h3>모둠별 잔여 코인</h3><div class="table-wrap"><table><thead><tr><th>모둠</th><th>방식</th><th>잔액</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${u.periodLimit===null?`하루 ${u.dailyLimit}개`:`기간 전체 ${u.periodLimit}개`}</td><td>${u.balance}개</td><td><button class="btn secondary small" data-edit-user="${u.id}">한도 · 코인 조정</button></td></tr>`).join('')}</tbody></table></div></div>`:`<div class="stats">${stat('사용 가능한 코인',state.user.balance,'개',state.user.periodLimit===null?`하루 기본 ${state.user.dailyLimit}개`:'프로젝트 전체 기간')}</div>`}<section class="panel"><h3>코인 내역</h3>${entries.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th>${isTeacher()?'<th>모둠</th>':''}<th>내용</th><th>변동</th></tr></thead><tbody>${entries.map(l=>`<tr><td>${date(l.created_at)}</td>${isTeacher()?`<td>${esc(l.name)}</td>`:''}<td>${esc(l.reason)}</td><td>${l.delta>0?'+':''}${l.delta}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">아직 코인 사용 내역이 없습니다.</div>'}<p class="tiny muted">${isTeacher()?'최근 500건':'최근 100건'}까지 표시됩니다.</p></section>`);}catch(e){toast(e.message);}}
function render(){if(!state.user)return;const pages={home,new:newRequest,history,requests:history,detail,users,settings};if(state.page==='growth'){void growthPage();return;}if(state.page==='coins'){coins();return;}shell((pages[state.page]||home)());}
const growthTitles={before:'처음에는',now:'이번에는',growth:'이렇게 성장했어요',resultChange:'컨설팅 결과의 변화',next:'다음에는',teacherNarrative:'교사용 성장 서술',teacherGuidance:'다음 의뢰 지도 사항',initial:'초기 의뢰의 특징',changes:'의뢰 과정의 주요 변화',strongest:'가장 뚜렷하게 확인된 변화'};
const growthDate=value=>value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';
function growthQuotes(evidence=[]){return evidence.map(e=>`<blockquote class="growth-quote"><span class="tiny muted">의뢰 #${e.requestId}</span><p>“${esc(e.quote)}”</p></blockquote>`).join('');}
function growthReportCard(record,data){
 const teacher=isTeacher(),report=record.report,summary=record.kind==='summary',current=data.history.find(r=>r.id===record.requestId),previous=data.history.find(r=>r.id===record.comparisonId);
 const pending=['pending','running'].includes(record.status),keys=summary?['initial','changes','strongest','next']:['before','now','growth','resultChange','next'];
 const statuses={pending:'분석 대기',running:'분석 중',review:'선생님 검토 중',approved:'검토 완료',error:'분석 재시도 필요'};
 return `<section class="panel growth-card"><div class="row wrap"><h3 class="grow">${summary?'종합 성장 기록':`${current?.sequence||''}번째 의뢰 · ${esc(current?.title||activities[current?.activity]?.name||names[current?.type]||'의뢰 #'+record.requestId)}`}</h3><span class="tag">${statuses[record.status]}</span></div><p class="tiny muted">${record.source==='ai'?(record.status==='approved'?'교사가 검토한 AI 성장 기록':'AI 분석 초안 · 교사 검토 필요'):record.source==='observation'?'원문 관찰 기록 · AI 성장 판단 아님':record.source==='teacher'?'교사가 작성한 성장 기록':'의뢰 원문을 바탕으로 준비 중'}${record.reviewedAt?' · 검토일 '+growthDate(record.reviewedAt):''}</p>${!summary?`<details class="growth-comparison"><summary>이전 의뢰와 이번 의뢰 원문 비교</summary><p class="tiny">${previous?(previous.activity===current?.activity?'같은 활동의 이전 의뢰 또는 연결된 수정 원본입니다.':'질문이 다른 활동입니다. 공통 영역만 비교하고 활동별 차이를 함께 확인해 주세요.'):'비교할 이전 의뢰가 없어 현재 특징만 살펴봅니다.'}</p><div class="two-col">${[previous,current].map((r,i)=>`<div><h4>${i?'이번 의뢰':'이전 의뢰'}</h4>${r?`<p class="tiny">#${r.id} · ${growthDate(r.createdAt)}</p>${answers(r)}`:'<p>이전 자료가 없어요.</p>'}</div>`).join('')}</div></details>`:''}${report?`<dl class="growth-narrative">${keys.map(key=>`<div><dt>${growthTitles[key]}</dt><dd>${esc(report[key])}</dd></div>`).join('')}</dl>${report.areas?.length?`<details><summary>활동에 맞춘 영역별 관찰과 실제 문장 근거</summary>${report.areas.map(a=>`<div class="growth-area"><h4>${globalThis.growthPolicy.labels[a.key]}</h4><p>${esc(a.finding)}</p>${growthQuotes(a.evidence)}</div>`).join('')}</details>`:''}${report.examples?.length?`<details><summary>실제 의뢰 문장의 변화 사례</summary>${report.examples.map(e=>`${growthQuotes([e.before,e.after].filter(Boolean))}<p>${esc(e.description)}</p>`).join('')}</details>`:''}${report.resultEvidence?.length?`<details><summary>결과 설명에서 확인한 근거</summary>${growthQuotes(report.resultEvidence)}</details>`:''}`:`<p class="notice">${teacher?'성장 기록을 준비하고 있습니다. 분석이 실패한 경우 원문을 보고 직접 서술하거나 다시 분석할 수 있습니다.':'선생님이 원문과 분석 내용을 살펴보고 있어요. 검토가 끝나면 여기에서 확인할 수 있어요.'}</p>`}${teacher?`${record.error?`<div class="inline-error" role="alert">${esc(record.error)}</div>`:''}${!pending?`<form data-growth-review="${record.id}"><h4 style="margin-top:18px">기록 수정과 검토</h4>${[...keys,'teacherNarrative',...(summary?[]:['teacherGuidance'])].map(key=>`<label class="field"><span>${growthTitles[key]}</span><textarea name="${key}" maxlength="4000" required>${esc(report?.[key]||'')}</textarea></label>`).join('')}${report?.areas?.map(a=>`<label class="field"><span>${globalThis.growthPolicy.labels[a.key]} · 관찰 내용</span><textarea name="area-${a.key}" maxlength="4000">${esc(a.finding)}</textarea></label>`).join('')||''}${report?.examples?.map((e,i)=>`<label class="field"><span>사례 ${i+1} 설명</span><textarea name="example-${i}" maxlength="4000">${esc(e.description)}</textarea></label>`).join('')||''}<label class="check"><input name="reviewConfirmed" type="checkbox"><span>원문 인용과 활동 차이, 결과의 실제 변화 여부를 확인했습니다. 점수나 입력량으로 성장 여부를 단정하지 않았습니다.</span></label><div class="inline-error" data-growth-error="${record.id}" role="alert"></div><div class="row wrap"><button class="btn secondary" name="save" type="submit">수정 내용 저장</button><button class="btn" name="approve" type="submit">검토 완료 · 학생에게 공개</button><button class="text-btn" data-growth-retry="${record.id}" type="button">다시 분석</button></div></form>`:''}${record.revisions?.length?`<details><summary>생성·수정·검토 이력 (${record.revisions.length})</summary>${record.revisions.map(v=>`<div class="growth-area"><p class="tiny">${growthDate(v.created_at)} · ${{generated:'자동 생성',edited:'교사 수정',approved:'교사 승인'}[v.action]}</p><p>${esc(v.data.teacherNarrative||v.data.growth||v.data.changes)}</p></div>`).join('')}</details>`:''}`:''}</section>`;
}
async function growthPage(){
 const teacher=isTeacher(),userId=teacher?(state.growthUserId||state.users[0]?.id):state.user.id,session=state.user.id,token=++growthPage.token;
 const title=teacher?'모둠별 성장 분석':'나의 성장 기록';
 const controls=`<div class="row wrap no-print">${teacher?`<label class="field"><span>모둠 선택</span><select id="growth-group">${state.users.map(u=>`<option value="${u.id}" ${u.id===userId?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label>`:''}<button class="btn secondary small" data-growth-refresh>기록 새로고침</button><button class="btn secondary small" data-action="print">성장 기록 출력</button></div>`;
 const header=heading('OUR LEARNING JOURNEY',title,'의뢰에 담긴 생각과 실제 결과를 함께 살펴봐요. 점수나 순위로 비교하지 않아요.')+`<div class="growth-welcome"><img src="${brandAssets.robot}" alt="" width="80" height="106"><div><span class="eyebrow">ONE IDEA, ONE STEP FORWARD</span><h3>한 번 더 생각하고, 한 걸음 더 자라요.</h3><p>처음의 생각과 지금의 생각, 어떤 점이 달라졌을까요?</p></div><span class="welcome-flower" aria-hidden="true">✿</span></div>`;
 if(!userId){shell(header+'<div class="empty">먼저 모둠 계정을 추가해 주세요.</div>');return;}
 state.growthUserId=userId;shell(header+controls+'<div class="loading-note">성장 기록을 불러오고 있어요…</div>');
 try{
  const data=await api('/growth'+(teacher?'?userId='+userId:''));
  if(state.page!=='growth'||state.user?.id!==session||growthPage.token!==token)return;
  state.growthData=data;const first=data.history[0],last=data.history.at(-1),summary=data.records.find(r=>r.kind==='summary');
  shell(header+controls+`<div class="notice">모둠 계정으로 남긴 기록입니다. 개인별 활동을 구분해 기록하지 않았다면 한 학생의 성장으로 단정하지 않아요.${teacher?' AI 분석과 교사 관찰을 구분하고, 실제 문장 근거를 검토한 뒤 공개해 주세요.':' 선생님이 검토한 성장 피드백만 볼 수 있어요.'}</div>${!data.history.length?'<div class="empty">첫 의뢰를 보내면 성장 여정이 시작돼요.</div>':`<section class="panel growth-card"><h3>처음 의뢰와 최근 의뢰</h3><p class="tiny">활동과 질문이 다르면 직접적인 우열을 판단하지 않아요.</p><div class="two-col">${[first,last].map((r,i)=>`<div><h4>${i?'최근 의뢰':'처음 의뢰'} · ${r.sequence}번째</h4><p class="tiny">${growthDate(r.createdAt)}</p>${answers(r)}</div>`).join('')}</div></section>${summary?growthReportCard(summary,data):''}<section class="panel growth-card"><h3>지금까지의 컨설팅 의뢰 이력</h3>${data.history.map(r=>`<details class="growth-area"><summary>${r.sequence}번째 · ${growthDate(r.createdAt)} · ${esc(activities[r.activity]?.name||names[r.type])}${r.parentId?' · 원본 #'+r.parentId+' 수정':''}</summary>${answers(r)}${r.final?`<h4>교사가 승인한 최종 결과</h4>${r.final.candidates.map(c=>`<h4>${esc(c.title)}</h4>${resultContent(c.content)}${c.imageUrl?`<img class="design-preview" src="${esc(c.imageUrl)}" alt="교사가 승인한 디자인 결과">`:''}`).join('')}`:'<p class="tiny">컨설팅 결과 검토 중</p>'}<button class="text-btn no-print" data-detail="${r.id}">의뢰서와 이미지 보기 →</button>${teacher?data.events.filter(e=>e.requestId===r.id).map(e=>`<details><summary>${growthDate(e.createdAt)} · ${{submitted:'학생 제출 원문',ai_draft:'컨설팅 원본 초안',ai_image:'AI 생성 이미지',teacher_final:'교사 승인 최종본',legacy_snapshot:'기능 도입 전 보존본'}[e.kind]||e.kind}</summary>${e.data.originalAiDraftAvailable===false?'<p class="tiny">기능 도입 전 자료입니다. 교사 수정 전의 원래 AI 초안은 복구할 수 없습니다.</p>':''}${studentSketchFigure({id:e.requestId,sketch:e.data.sketch})}${e.data.candidates?.map(c=>`<h4>${esc(c.title)}</h4>${resultContent(c.content)}`).join('')||''}${e.data.images?.map(img=>`<img class="design-preview" src="${img.imageUrl}" alt="보존된 컨설팅 이미지">`).join('')||''}</details>`).join(''):''}</details>`).join('')}</section>${data.records.filter(r=>r.kind==='request').map(r=>growthReportCard(r,data)).join('')}`}`);
 }catch(error){if(state.page==='growth'&&growthPage.token===token)shell(header+controls+`<div class="inline-error" role="alert">${esc(error.message)}</div>`);}
}
growthPage.token=0;
function bindGrowth(){
 if($('#growth-group'))$('#growth-group').onchange=e=>{state.growthUserId=Number(e.target.value);void growthPage();};
 document.querySelectorAll('[data-growth-refresh]').forEach(button=>button.onclick=()=>void growthPage());
 document.querySelectorAll('[data-growth-retry]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/growth/'+button.dataset.growthRetry+'/retry','POST',{});await growthPage();toast('성장 기록을 다시 분석합니다. 잠시 뒤 새로고침해 주세요.');}catch(error){toast(error.message);button.disabled=false;}});
 document.querySelectorAll('[data-growth-review]').forEach(form=>form.onsubmit=async event=>{
  event.preventDefault();const id=Number(form.dataset.growthReview),record=state.growthData.records.find(r=>r.id===id),fields=new FormData(form),report=Object.fromEntries([...fields].filter(([key])=>key in growthTitles));
  if(record.report?.areas)report.areas=record.report.areas.map(a=>({key:a.key,finding:fields.get('area-'+a.key)}));
  if(record.report?.examples)report.examples=record.report.examples.map((e,i)=>({description:fields.get('example-'+i)}));
  const button=event.submitter;button.disabled=true;
  try{await api('/growth/'+id,'PATCH',{version:record.version,report,approve:button.name==='approve',reviewConfirmed:fields.has('reviewConfirmed')});await growthPage();toast(button.name==='approve'?'검토한 성장 기록을 학생에게 공개했습니다.':'수정 내용을 저장했습니다.');}catch(error){document.querySelector(`[data-growth-error="${id}"]`).textContent=error.message;button.disabled=false;}
 });
}
function modalUser(id){const u=state.users.find(u=>u.id===id);const el=document.createElement('div');el.className='modal-bg';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="row"><h2 id="modal-title" class="grow">${u?esc(u.name)+' 관리':'모둠 계정 추가'}</h2><button class="text-btn" id="close-modal" aria-label="닫기">✕</button></div><form id="user-form">${u?`<p class="tiny" style="margin-bottom:15px">아이디: ${esc(u.username)} · 현재 ${u.balance}개</p><label class="field"><span>새 비밀번호 (변경할 때만)</span><input name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password"></label>`:`${field('name','모둠 이름','예: 바다를 담은 1모둠')}${field('username','로그인 아이디','예: jeju01')}${field('password','초기 비밀번호','10자 이상',true,'password')}`}<div class="two-col">${field('dailyLimit','하루 기본 코인 (0~100)','',true,'number',u?.dailyLimit??3)}${u?`<label class="field"><span>코인 운영 방식</span><select name="mode"><option value="daily" ${u.periodLimit===null?'selected':''}>하루마다 초기화</option><option value="period" ${u.periodLimit!==null?'selected':''}>프로젝트 기간 전체</option></select></label>`:''}</div>${u?`${field('periodLimit','기간 전체 한도 (기간 모드 선택 시)','',false,'number',u.periodLimit??30)}<div class="notice">운영 방식 또는 기간 한도를 변경하면 잔액이 해당 한도로 초기화됩니다. 하루 기본 코인 변경은 다음 날부터 적용됩니다.</div><div class="two-col">${field('adjustment','즉시 추가·삭감 (예: 2 또는 -1)','',false,'number',0)}${field('reason','조정 이유','예: 추가 활동 보상',false)}</div><label class="check"><input name="active" type="checkbox" ${u.active?'checked':''}><span>계정 사용 허용</span></label>`:''}<div id="user-error" class="inline-error" role="alert"></div><button class="btn" type="submit">${u?'변경사항 저장':'모둠 만들기'}</button></form></section>`;document.body.appendChild(el);const close=()=>{el.remove();document.removeEventListener('keydown',onKey);};const onKey=e=>{if(e.key==='Escape')close();};document.addEventListener('keydown',onKey);$('#close-modal').onclick=close;el.onclick=e=>{if(e.target===el)close();};el.querySelector('input').focus();$('#user-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.dailyLimit=Number(b.dailyLimit);if(u){if(!b.password)delete b.password;b.active=e.target.active.checked;b.adjustment=Number(b.adjustment||0);const limit=b.mode==='period'?Number(b.periodLimit):null;if(limit!==u.periodLimit)b.periodLimit=limit;else delete b.periodLimit;delete b.mode;}e.submitter.disabled=true;try{await api(u?`/users/${u.id}`:'/users',u?'PATCH':'POST',b);close();await load();render();toast(u?'모둠 설정을 저장했습니다.':'모둠 계정을 만들었습니다.');}catch(err){$('#user-error').textContent=err.message;e.submitter.disabled=false;}};}
function bind(){bindGrowth();bindStudentSketch();const nav=document.querySelector('.nav'),active=document.querySelector('.nav button.active');if(nav&&active&&nav.scrollWidth>nav.clientWidth)nav.scrollLeft=Math.max(0,active.offsetLeft-nav.offsetLeft-(nav.clientWidth-active.clientWidth)/2);document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.detail=null;state.parent=null;state.filter={};render();window.scrollTo(0,0);});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.formType=b.dataset.type;state.page='new';state.parent=null;render();window.scrollTo(0,0);});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.detail=Number(b.dataset.detail);state.page='detail';render();window.scrollTo(0,0);});document.querySelectorAll('[data-followup]').forEach(b=>b.onclick=()=>{state.parent=Number(b.dataset.followup);state.formType='revision';state.activity='D1';state.page='new';render();window.scrollTo(0,0);});document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>modalUser(Number(b.dataset.editUser)));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{const a=b.dataset.action;if(a==='logout'){await api('/logout','POST',{});state.requestDrafts={};state.sketchDrafts={};state.user=null;auth(false);}if(a==='print')window.print();if(a==='add-user')modalUser();if(a==='reset-filter'){state.filter={};render();}}catch(e){toast(e.message);}});
 for(const [id,key] of [['search','q'],['filter-status','status'],['filter-group','group'],['filter-date','date']]){const el=$('#'+id);if(el)el.onchange=()=>{state.filter[key]=el.value;render();};}
 if($('#type-select'))$('#type-select').onchange=e=>{saveRequestDraft();state.formType=e.target.value;state.activity=null;state.parent=null;render();};
 if($('#activity-select'))$('#activity-select').onchange=e=>{saveRequestDraft();state.activity=e.target.value;render();};
 if($('#parent-select'))$('#parent-select').onchange=e=>{saveRequestDraft();state.parent=Number(e.target.value)||null;render();};
 if($('#request-form'))$('#request-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(e.target)),sketch=state.sketchDrafts[e.target.dataset.sketchKey];if(sketch?.loading)throw Error('그림 미리보기가 준비된 뒤 의뢰해 주세요.');if(sketch?.error)throw Error('그림을 다시 선택하거나 첨부 취소를 눌러 주세요.');const {id}=await api('/requests','POST',{type:b.type,activity:b.activity,sketch:sketch?.image||null,parentId:b.activity==='D1'?Number(b.parentId):null,answers:Object.fromEntries(['q1','q2','q3'].map(k=>[k,b[k]])),safetyConfirmed:!!b.safety});delete state.requestDrafts[b.activity];delete state.sketchDrafts[e.target.dataset.sketchKey];await load();state.detail=id;state.page='detail';render();window.scrollTo(0,0);toast('의뢰서를 보냈어요. 코인 1개를 사용했습니다.');}catch(err){$('#form-error').textContent=err.message;e.submitter.disabled=false;}};
 document.querySelectorAll('[data-image]').forEach(b=>b.onclick=async()=>{if(!confirm('이미지 생성에는 별도 AI API 비용이 발생합니다. 현재 저장된 후보 내용과 학생의 의뢰를 바탕으로 생성할까요? 화면에서 수정 중인 내용은 전송할 때 저장됩니다.'))return;b.disabled=true;const old=b.textContent;b.textContent='이미지를 그리고 있어요…';try{await api(`/requests/${b.dataset.image}/images/${b.dataset.candidate}`,'POST',{});await load();render();toast('시안 이미지가 준비되었습니다. 전송 전 검토해 주세요.');}catch(e){toast(e.message);b.disabled=false;b.textContent=old;}});
 document.querySelectorAll('[data-generate]').forEach(b=>b.onclick=async()=>{const r=state.requests.find(r=>r.id===Number(b.dataset.generate));if(state.aiEnabled&&r.answers.activity&&(r.outputType||r.type)==='design'&&!confirm('후보 설명과 실제 디자인 이미지 3개를 생성합니다. 별도 이미지 API 비용이 발생합니다. 진행할까요?'))return;b.disabled=true;const old=b.textContent;b.textContent='후보를 작성하고 있어요…';try{await api(`/requests/${b.dataset.generate}/generate`,'POST',{});await load();render();toast('후보 3개가 준비되었습니다. 검토 후 전송해 주세요.');}catch(err){await load();render();const target=$('#generate-error');if(target)target.textContent=err.message;else toast(err.message);}});
 if($('#manual-design-form')){
  const form=$('#manual-design-form');let image=null;
  form.elements.image.onchange=async()=>{image=null;$('#manual-preview').hidden=true;$('#manual-error').textContent='';const file=form.elements.image.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('PNG, JPEG, WebP 이미지를 5MB 이하로 첨부해 주세요.');image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('이미지를 읽을 수 없습니다.'));reader.readAsDataURL(file);});$('#manual-preview').src=image;$('#manual-preview').hidden=false;}catch(err){form.elements.image.value='';$('#manual-error').textContent=err.message;}};
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);e.submitter.disabled=true;form.elements.image.disabled=true;try{if(f.get('image')?.size&&!image)throw Error('이미지 미리보기가 준비된 후 전송해 주세요.');await api(`/requests/${state.detail}/release`,'POST',{manual:{title:f.get('title'),summary:f.get('summary'),content:f.get('content'),image},teacherNote:f.get('teacherNote'),reviewConfirmed:!!f.get('reviewConfirmed')});await load();render();toast('직접 작성한 디자인을 모둠에 전송했습니다.');}catch(err){$('#manual-error').textContent=err.message;e.submitter.disabled=false;form.elements.image.disabled=false;}};
 }
 if($('#release-form'))$('#release-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const r=state.requests.find(r=>r.id===state.detail);const b={selected:f.getAll('selected').map(Number),candidates:r.candidates.map(c=>({id:c.id,title:f.get('title-'+c.id),summary:f.get('summary-'+c.id),content:f.get('content-'+c.id)})),assessment:{score:Number(f.get('score')),strengths:f.get('strengths').split('\n').filter(x=>x.trim()),improvements:f.get('improvements').split('\n').filter(x=>x.trim()),safety:f.get('safety')},teacherNote:f.get('teacherNote'),reviewConfirmed:!!f.get('reviewConfirmed')};e.submitter.disabled=true;try{await api(`/requests/${r.id}/release`,'POST',b);await load();render();toast('선택한 결과와 평가를 모둠에 전송했습니다.');}catch(err){$('#release-error').textContent=err.message;e.submitter.disabled=false;}};
 if($('#password-form'))$('#password-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api('/password','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('비밀번호를 변경했습니다.');}catch(err){$('#password-error').textContent=err.message;}finally{e.submitter.disabled=false;}};
}
